/* Austauschbare Kursdaten. Keine Schülerdaten und kein ausführbarer Upload. */
(function(root){
'use strict';
const clone=x=>JSON.parse(JSON.stringify(x)),base=clone(root.BioCasaDefaultData||root.BioCasaDataConfig),topics=['inventory','inventar','balance','accounts','income','tax','further','returns','accrual','stock','control'];
const fail=message=>{throw Error('Datenbasis: '+message);};
const obj=x=>{if(!x||typeof x!=='object'||Array.isArray(x))fail('Ein Datenobjekt fehlt.');return x;};
const str=(x,max=400)=>{if(typeof x!=='string'||x.length>max||/[<>]/.test(x))fail('Ungültiger Text im Datensatz.');return x;};
const amount=x=>{if(typeof x!=='number'||!Number.isFinite(x)||x<0||x>10000000||Math.abs(x*100-Math.round(x*100))>.00001)fail('Geldbeträge müssen nicht negative Eurobeträge mit höchstens zwei Nachkommastellen sein.');return Math.round(x*100);};
const quantity=(x,max=1000000)=>{if(!Number.isFinite(x)||x<0||x>max||Math.abs(x*100-Math.round(x*100))>.00001)fail('Ungültige Menge.');return x;};
const list=(x,max)=>{if(!Array.isArray(x)||x.length>max)fail('Eine Liste fehlt oder ist zu groß.');return x;};
function hash(text){let a=2166136261,b=3339675911;for(const c of text){a=Math.imul(a^c.charCodeAt(0),16777619);b=Math.imul(b^c.charCodeAt(0),2246822519);}return (a>>>0).toString(36)+(b>>>0).toString(36);}
function stable(x){return JSON.stringify(x&&typeof x==='object'?!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,JSON.parse(stable(x[k]))])):x.map(v=>JSON.parse(stable(v))):x);}
function fingerprint(d){return 'bc11-'+hash(stable({year:d.caseYear,opening:d.openingBalances,products:d.products,entries:d.demoEntries,inventory:d.practiceInventory,simulation:d.pizzaSimulation,receipts:d.receipts}));}
function validate(input,accounts=null,productMeta=null){
 obj(input);if(JSON.stringify(input).length>100000)fail('Der Datensatz überschreitet 100 KB.');
 const d=clone(input);if(d.format!=='BioCasaDataset'||d.version!==1||d.grade!==11)fail('Wähle einen BioCasa-Datensatz der Version 1 für Klasse 11.');
 if(!Number.isInteger(d.caseYear)||d.caseYear<2000||d.caseYear>2100||d.schoolYear!==d.caseYear+'/'+String((d.caseYear+1)%100).padStart(2,'0'))fail('Schuljahr und Falljahr passen nicht zusammen, z. B. 2027/28 und 2027.');
 str(d.label,100);obj(d.source);for(const k of ['title','reference','bookEdition','bookSource'])str(d.source[k],400);
 obj(d.openingBalances);for(const [id,value] of Object.entries(d.openingBalances)){if(!/^\d{3,4}$/.test(id))fail('Ungültige Kontonummer.');amount(value);}
 const date=s=>{if(typeof s!=='string'||s<d.caseYear+'-10-01'||s>d.caseYear+'-12-31'||!/^\d{4}-\d{2}-\d{2}$/.test(s)||!Number.isFinite(Date.parse(s+'T00:00:00Z'))||new Date(s+'T00:00:00Z').toISOString().slice(0,10)!==s)fail('Ein Belegdatum liegt nicht im Rumpfzeitraum Oktober–Dezember des Falljahres.');};
 const lines=rows=>{list(rows,16);if(rows.length<2)fail('Ein Beleg braucht mindestens zwei Kontenzeilen.');let debit=0,credit=0;for(const r of rows){if(!Array.isArray(r)||r.length!==3||!/^\d{3,4}$/.test(r[0]))fail('Ungültige Kontenzeile.');const a=amount(r[1]),b=amount(r[2]);if((a===0)===(b===0))fail('Jede Kontenzeile braucht genau einen Soll- oder Habenbetrag.');debit+=a;credit+=b;if(accounts&&!accounts.some(a=>a.id===r[0]))fail('Unbekanntes Konto '+r[0]+'.');}if(debit!==credit)fail('Soll und Haben eines Belegs sind nicht ausgeglichen.');return debit;};
 list(d.products,3);if(d.products.length!==3||new Set(d.products.map(p=>p.id)).size!==3)fail('Die drei bekannten Roh-/Hilfsstoffartikel müssen enthalten sein.');for(const p of d.products){if(!base.products.some(b=>b.id===p.id)||!amount(p.cost)||!Number.isInteger(p.opening)||!Number.isInteger(p.minimum))fail('Ungültiger Artikel.');quantity(p.opening,100000);quantity(p.minimum,100000);}
 list(d.demoEntries,30);if(d.demoEntries.length<15)fail('Die 15 bestehenden Grundlagen-/Demobelege bilden die bisherige Lernstruktur.');for(const [index,e] of d.demoEntries.entries()){date(e.date);str(e.text,120);str(e.reference,40);if(!['md','practice'].includes(e.origin))fail('Belegherkunft muss md oder practice sein.');lines(e.lines);if(index<15){const shape=rows=>rows.map(l=>[l[0],l[1]>0?'d':'c']).sort().join('|');if(shape(e.lines)!==shape(base.demoEntries[index].lines))fail('Die Kontoarten und Buchungsseiten der ersten 15 Belege müssen zur bestehenden Lernstruktur passen. Werte und Falljahr dürfen sich ändern.');}if(e.movement){const m=e.movement;obj(m);if(!d.products.some(p=>p.id===m.productId)||!['purchase','consumption','loss'].includes(m.kind)||!Number.isInteger(m.qty)||m.qty===0||Math.abs(m.qty)>100000||(m.kind==='purchase')!==(m.qty>0))fail('Ungültige Lagerbewegung.');amount(m.net);amount(m.vat);}}
 obj(d.practiceInventory);for(const [id,original] of Object.entries(base.practiceInventory)){const p=obj(d.practiceInventory[id]);if(Object.keys(p).sort().join()!=Object.keys(original).sort().join())fail('Unvollständiger Inventurfall '+id+'.');for(const [key,v] of Object.entries(p))key==='price'?amount(v):quantity(v);if(['flour','pizza'].includes(id))for(const key of id==='flour'?['bags','foreignBags']:['boxes','perBox','singles'])if(!Number.isInteger(p[key]))fail('Sack- und Stückzahlen müssen ganzzahlig sein.');}const i=d.practiceInventory;if(i.cutoff.count+i.cutoff.incoming<i.cutoff.outgoing||i.permanent.count+i.permanent.incoming<i.permanent.outgoing)fail('Ein Inventurfall hätte einen negativen Bestand.');
 list(d.pizzaSimulation,3);if(d.pizzaSimulation.length!==3||new Set(d.pizzaSimulation.map(p=>p.id)).size!==3)fail('Drei Pizzasorten müssen enthalten sein.');for(const p of d.pizzaSimulation){if(!['P1','P2','P3'].includes(p.id))fail('Unbekannte Pizzasorte.');str(p.name,70);amount(p.price);amount(p.cost);}
 list(d.receipts,15);const receiptIds=new Set(),references=new Set();for(const r of d.receipts){if(!/^[a-z]{1,24}$/.test(r.id)||receiptIds.has(r.id)||references.has(r.reference))fail('Belegkennungen müssen eindeutig sein.');receiptIds.add(r.id);references.add(r.reference);r.entryText=r.entryText||r.title;str(r.entryText,120);for(const k of ['reference','kind','partner','title','text'])str(r[k],k==='text'?600:120);date(r.date);if(![4,5,6,7,8].includes(r.min))fail('Ungültiger Lernschritt am Übungsbeleg.');list(r.lines,8);if(r.lines.some(l=>!Array.isArray(l)||l.length!==2))fail('Ungültige Belegposition.');let total=0;for(const l of r.lines){str(l[0],120);total+=amount(l[1]);}if(total!==amount(r.total)||lines(r.posting)!==total)fail('Belegpositionen, Belegsumme und Kontierung stimmen nicht überein.');}
 obj(d.bookReferences);for(const [key,refs] of Object.entries(d.bookReferences)){if(!topics.includes(key))fail('Unbekanntes Thema im Buchverweis.');for(const r of list(refs,5)){str(r.topic,100);str(r.prompt,400);if(typeof r.pages!=='string'||!r.pages||!/^\d[\d\s,–\-]*$/.test(r.pages)||r.pages.length>90)fail('Ungültige Seitenfundstelle.');}}
 for(const a of list(d.assumptions,15)){if(!['md','practice'].includes(a.origin))fail('Ungültige Herkunft einer Annahme.');str(a.title,100);str(a.basis,1000);}
 if(accounts){
  const by=Object.fromEntries(accounts.map(a=>[a.id,a])),balance=Object.fromEntries(accounts.map(a=>[a.id,amount(d.openingBalances[a.id]||0)])),qty=Object.fromEntries(d.products.map(p=>[p.id,p.opening]));
  for(const id of Object.keys(d.openingBalances))if(!by[id])fail('Unbekanntes Eröffnungskonto '+id+'.');
  if(accounts.some(a=>['expense','revenue'].includes(a.type)&&balance[a.id]))fail('Erfolgskonten starten ohne Anfangsbestand.');
  const assets=accounts.filter(a=>a.type==='asset').reduce((n,a)=>n+balance[a.id],0),passives=accounts.filter(a=>['liability','equity'].includes(a.type)).reduce((n,a)=>n+balance[a.id],0);if(assets!==passives)fail('Die Eröffnungsbilanz ist nicht ausgeglichen.');
  if(productMeta)for(const account of ['200','202']){const value=d.products.filter(p=>productMeta.find(m=>m.id===p.id)?.account===account).reduce((n,p)=>n+p.opening*amount(p.cost),0);if(value!==balance[account])fail('Mengenbestand und Eröffnungswert des Vorratskontos '+account+' passen nicht zusammen.');}
  let last='';for(const e of d.demoEntries){if(e.date<last)fail('Sortiere die Demobelege nach Datum.');last=e.date;for(const [id,debit,credit] of e.lines)balance[id]+=(['asset','expense'].includes(by[id].type)?1:-1)*(amount(debit)-amount(credit));if(accounts.some(a=>a.type==='asset'&&balance[a.id]<0))fail('Demobeleg '+e.reference+' würde einen Vermögensbestand ins Minus bringen.');if(e.movement&&productMeta){const m=e.movement,p=d.products.find(p=>p.id===m.productId),meta=productMeta.find(p=>p.id===m.productId),stock=e.lines.filter(l=>l[0]===meta.account).reduce((n,l)=>n+amount(l[1])-amount(l[2]),0);if(stock!==m.qty*amount(p.cost))fail('Menge und Finanzbuchung von '+e.reference+' passen nicht zusammen.');if(m.kind==='purchase'&&amount(m.net)!==stock)fail('Der Nettowert des Materialeinkaufs passt nicht.');qty[p.id]+=m.qty;if(qty[p.id]<0)fail('Ein Demobeleg führt zu negativem Lagerbestand.');}else if(e.lines.some(l=>['200','202'].includes(l[0])))fail('Vorratskonten benötigen eine passende Lagerbewegung.');}
 }
 return d;
}
function shiftYear(input,year){const d=clone(input);d.caseYear=Number(year);d.schoolYear=d.caseYear+'/'+String((d.caseYear+1)%100).padStart(2,'0');for(const e of [...d.demoEntries,...d.receipts])e.date=d.caseYear+e.date.slice(4);return d;}
function source(d){return '/* Kursdaten in Euro; keine persönlichen Bearbeitungsstände. */\nglobalThis.BioCasaDataConfig='+JSON.stringify(d).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029')+';\n';}
let selected=root.BioCasaDataConfig;try{if(root.window?.location?.pathname.endsWith('/preview.html')){const raw=root.window.localStorage?.getItem('biocasa-os:teacher-dataset');if(raw)selected=validate(JSON.parse(raw));}}catch{selected=base;}
const current=validate(selected),identity=fingerprint(current),legacyCompatible=identity===fingerprint(validate(base));
root.BioCasaData=Object.freeze({current,defaultConfig:validate(base),identity,legacyCompatible,validate,shiftYear,source,fingerprint,amount,clone});
})(globalThis);
